INSERT INTO rule_sections (id, title, position) VALUES (1, 'Общие положения', 1);
INSERT INTO rules (section_id, body_md, position) VALUES (1, 'Заходя на сервер или в наш Discord, вы принимаете эти правила. Незнание правил не освобождает от ответственности.', 1);
INSERT INTO rules (section_id, body_md, position) VALUES (1, 'Правила одинаковы для всех: для новичков, старожилов, друзей администрации и самих администраторов.', 2);
INSERT INTO rules (section_id, body_md, position) VALUES (1, 'Если ситуация не описана в правилах, решение принимает администрация, исходя из здравого смысла и интересов сообщества. Дух правил важнее буквы: поиск лазеек тоже считается нарушением.', 3);
INSERT INTO rules (section_id, body_md, position) VALUES (1, 'Заходить с другого аккаунта, чтобы обойти мут или бан, запрещено.', 4);
INSERT INTO rule_sections (id, title, position) VALUES (2, 'Игровой процесс', 2);
INSERT INTO rules (section_id, body_md, position) VALUES (2, '**Гриф запрещён.** Нельзя ломать, перестраивать, поджигать или затапливать чужие постройки, разорять поля и грядки, вытаптывать посевы, рубить чужие сады, разбирать механизмы и редстоун-схемы. Даже если постройка выглядит заброшенной: сначала спросите администрацию.', 1);
INSERT INTO rules (section_id, body_md, position) VALUES (2, '**Воровство запрещено.** Брать вещи из чужих сундуков, ящиков, полок, печей, бочек, шалкеров и других хранилищ можно только с разрешения владельца. Незапертый сундук не означает разрешения.', 2);
INSERT INTO rules (section_id, body_md, position) VALUES (2, '**PvP полностью запрещено.** Нельзя атаковать других игроков, убивать их, сталкивать в пропасть, воду или лаву, строить на них ловушки и заманивать к мобам. Дуэлей «по согласию» тоже нет: сражаемся только с монстрами.', 3);
INSERT INTO rules (section_id, body_md, position) VALUES (2, '**Чужих животных не трогать.** Нельзя убивать, уводить и забирать одомашненных животных и питомцев других игроков.', 4);
INSERT INTO rules (section_id, body_md, position) VALUES (2, '**Уважайте соседей.** Не стройте вплотную к чужим постройкам без согласия владельца и не занимайте землю вокруг чужого дома.', 5);
INSERT INTO rules (section_id, body_md, position) VALUES (2, '**Читы и эксплойты запрещены.** X-ray, автокликеры, дюп предметов, сторонние программы и клиентские моды, дающие нечестное преимущество, а также использование багов. Нашли баг — сообщите администрации, за это не наказывают.', 6);
INSERT INTO rules (section_id, body_md, position) VALUES (2, '**Берегите сервер.** Не стройте огромные механизмы и фермы, из-за которых лагает сервер, и не уродуйте мир: не оставляйте столбы до неба и изрытую землю возле спавна и чужих домов. Если постройка грузит сервер, администрация может попросить её переделать.', 7);
INSERT INTO rules (section_id, body_md, position) VALUES (2, '**Общие места — общие.** Спавн, дороги и общественные постройки нельзя присваивать, разбирать и перестраивать без согласования с администрацией.', 8);
INSERT INTO rule_sections (id, title, position) VALUES (3, 'Общение и чат', 3);
INSERT INTO rules (section_id, body_md, position) VALUES (3, '**Уважайте друг друга.** Запрещены оскорбления, травля, унижение и провокации. Нельзя высмеивать игрока за национальность, язык, пол, возраст, религию, внешность или уровень игры.', 1);
INSERT INTO rules (section_id, body_md, position) VALUES (3, '**Никакой политики.** Запрещены любые обсуждения политики, войны, политиков и государств в политическом смысле, а также политические символы, флаги, лозунги и мемы. Это касается чата, ников, построек, табличек и картин в игре.', 2);
INSERT INTO rules (section_id, body_md, position) VALUES (3, '**Мат разрешён в меру.** Выругаться от души можно, но:\n- нельзя материться в адрес другого игрока\n- нельзя превращать мат в каждое слово или спамить им\n- если собеседник просит сбавить тон, уважайте это', 3);
INSERT INTO rules (section_id, body_md, position) VALUES (3, '**Не устраивайте драк в чате.** Не разжигайте конфликты и срачи. Спор переносите в личные сообщения, а проблему с игроком решайте через администрацию, со скриншотами. Самосуд и месть запрещены.', 4);
INSERT INTO rules (section_id, body_md, position) VALUES (3, '**Три языка равноправны.** На сервере общаются на русском, украинском и английском. Нельзя требовать от других писать на «правильном» языке и смеяться над чужим языком.', 5);
INSERT INTO rules (section_id, body_md, position) VALUES (3, '**Без спама и рекламы.** Запрещены флуд, капс, повтор одного и того же сообщения, попрошайничество и реклама других серверов, проектов и Discord-каналов.', 6);
INSERT INTO rules (section_id, body_md, position) VALUES (3, '**Личное остаётся личным.** Нельзя публиковать чужие личные данные (имя, адрес, фото, контакты), угрожать в реальной жизни и выдавать себя за другого игрока или администрацию.', 7);
INSERT INTO rule_sections (id, title, position) VALUES (4, 'Контент 18+', 4);
INSERT INTO rules (section_id, body_md, position) VALUES (4, '**Любой контент 18+ запрещён** на сервере и в Discord, в любом виде: текст, картинки, ссылки, голос, постройки.', 1);
INSERT INTO rules (section_id, body_md, position) VALUES (4, 'Под запрет попадают:\n- порнография и эротика, включая «намёки», ссылки и описания\n- постройки, пиксель-арт, картины, таблички и надписи сексуального характера\n- сексуальные шутки, домогательства и сексуализация других игроков\n- ники, аватарки, скины и статусы с откровенным или пошлым содержанием\n- шок-контент: расчленёнка, реальная жестокость, кровь, гуро\n- пропаганда наркотиков, самоповреждения и суицида', 2);
INSERT INTO rules (section_id, body_md, position) VALUES (4, 'Любые сексуальные темы, связанные с несовершеннолетними, — **немедленный перманентный бан** на сервере и в Discord, без предупреждений, плюс жалоба в Discord.', 3);
INSERT INTO rules (section_id, body_md, position) VALUES (4, 'Сомневаетесь, можно ли это публиковать? Не публикуйте или сначала спросите администрацию.', 4);
INSERT INTO rules (section_id, body_md, position) VALUES (4, 'Увидели такой контент — не пересылайте его дальше. Сделайте скриншот и сообщите администрации.', 5);
INSERT INTO rule_sections (id, title, position) VALUES (5, 'Discord', 5);
INSERT INTO rules (section_id, body_md, position) VALUES (5, 'Наш Discord: [discord.gg/your-invite](https://discord.gg/your-invite). В нём действуют все правила общения и запрет контента 18+ из разделов выше.', 1);
INSERT INTO rules (section_id, body_md, position) VALUES (5, '**Пишите по теме канала.** Вопросы по игре, жалобы, предложения и оффтоп — в каналы, которые для этого предназначены.', 2);
INSERT INTO rules (section_id, body_md, position) VALUES (5, '**Не злоупотребляйте упоминаниями.** Нельзя массово пинговать участников, использовать @everyone и @here и без причины тегать администрацию.', 3);
INSERT INTO rules (section_id, body_md, position) VALUES (5, '**Голосовые каналы.** Не перебивайте и не кричите в микрофон, не включайте громкие звуки, саундпады и музыку через микрофон. Записывать разговор можно только с согласия всех участников.', 4);
INSERT INTO rules (section_id, body_md, position) VALUES (5, '**Профиль без нарушений.** Ник, аватар, статус и баннер профиля — без 18+, политики и оскорблений. Желательно, чтобы ник в Discord совпадал с игровым, так вас проще узнать.', 5);
INSERT INTO rules (section_id, body_md, position) VALUES (5, '**Безопасность.** Фишинговые ссылки, «бесплатный Nitro», фальшивые раздачи и любой скам — бан сразу. Администрация никогда не попросит у вас пароль или код от аккаунта игры или Discord.', 6);
INSERT INTO rules (section_id, body_md, position) VALUES (5, '**Без рекламы.** Приглашения на другие Discord-серверы и рекламные рассылки участникам в личные сообщения запрещены.', 7);
INSERT INTO rule_sections (id, title, position) VALUES (6, 'Наказания', 6);
INSERT INTO rules (section_id, body_md, position) VALUES (6, 'Наказание зависит от тяжести и повторности нарушения: предупреждение, мут, временный бан, перманентный бан.', 1);
INSERT INTO rules (section_id, body_md, position) VALUES (6, '**Бан сразу, без предупреждения:** читы и дюп, массовый гриф или воровство, контент 18+ с участием несовершеннолетних, публикация личных данных, угрозы, скам, обход бана.', 2);
INSERT INTO rules (section_id, body_md, position) VALUES (6, 'Нарушитель обязан возместить ущерб от грифа и воровства: вернуть вещи и восстановить разрушенное. По возможности администрация поможет пострадавшему.', 3);
INSERT INTO rules (section_id, body_md, position) VALUES (6, 'Решения администрации не обсуждаются в общем чате. Не согласны с наказанием — спокойно напишите администрации в [Discord](https://discord.gg/your-invite) и приложите доказательства: скриншоты, время, ники.', 4);
INSERT INTO rules (section_id, body_md, position) VALUES (6, 'Правила могут обновляться. Актуальная версия всегда на этой странице, о важных изменениях сообщим в новостях и в Discord.', 5);
INSERT INTO pages (slug, title, body_md) VALUES
    ('about', 'О сервере', '**MyServer** — сервер **Minecraft: Java Edition 26.3** для тех, кто любит неспешное выживание, стройку и живое сообщество. Стройте дом, объединяйтесь с соседями, торгуйте и переживайте ночи вместе.\n\n- **Мирный сервер**: PvP и гриф запрещены\n- **Заходите с любого лаунчера**: лицензия не нужна, ник защищён паролем на сайте\n- **Свой личный кабинет**: сколько наиграно, смена пароля, управление входами\n- **RU / UA / EN**: три языка, все равноправны'),
    ('start', 'Как начать играть', 'Чтобы начать играть на MyServer, достаточно пяти шагов.\n\n1. **Поставьте Minecraft: Java Edition 26.3.** Подойдёт любой лаунчер, лицензия не нужна.\n2. **Добавьте сервер.** Откройте **Сетевая игра** (Multiplayer), нажмите **Добавить** и введите адрес `example.com`. Адрес можно скопировать кнопкой ниже.\n3. **Пройдите проверку.** При первом входе игра попросит решить простой пример: это защита от ботов. Потом появится окно с кнопкой **«Нажмите, чтобы авторизоваться»**.\n4. **Подтвердите вход на сайте.** Кнопка откроет этот сайт. Новичок придумывает пароль, у кого аккаунт уже есть, вводит свой. Нажмите **«Подтвердить вход»**, и через пару секунд вы на сервере.\n5. **Прочитайте [правила](/rules).** Коротко: без грифа, без PvP, без политики и без контента 18+.\n\n## Частые вопросы\n\n**Нужна ли лицензия?** Нет. Ваш ник защищён паролем на сайте: под ним не зайдёт никто, кроме вас.\n\n**Придётся подтверждать вход каждый раз?** Нет. С того же IP игра пускает сразу 7 дней. Сменился IP или прошла неделя — игра снова даст ссылку.\n\n**Кто-то пытается зайти под моим ником.** На странице входа нажмите **«Это не я»**, а в [личном кабинете](/account) выйдите на всех устройствах и смените пароль.\n\n**Забыл пароль.** Напишите администрации в Discord, пароль сбросят.\n\n**Где задать вопрос или пожаловаться?** В нашем Discord, кнопка ниже. Там же новости и общение.');
INSERT INTO news (slug, title, body_md, is_published, is_pinned, published_at) VALUES
    ('welcome', 'Добро пожаловать на MyServer',
